ALTER FUNCTION public.summarize_user_activity() SET search_path=pg_catalog,public;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS catalog_runtime ON public.events;
DROP POLICY IF EXISTS app_read ON public.events;
DROP POLICY IF EXISTS app_insert ON public.events;
DROP POLICY IF EXISTS app_update ON public.events;
DROP POLICY IF EXISTS app_delete ON public.events;
DROP POLICY IF EXISTS maintenance ON public.events;
CREATE POLICY app_read ON public.events FOR SELECT TO personal_photos_app USING(event_id IN (SELECT photo_security.readable_events()));
CREATE POLICY app_insert ON public.events FOR INSERT TO personal_photos_app WITH CHECK((photo_security.flag('can_write') AND (owner_username=photo_security.username() OR photo_security.flag('main_admin'))) AND photo_security.assign_folder(folder_id));
CREATE POLICY app_update ON public.events FOR UPDATE TO personal_photos_app USING((photo_security.flag('can_write') AND (owner_username=photo_security.username() OR photo_security.flag('main_admin')))) WITH CHECK((photo_security.flag('can_write') AND (owner_username=photo_security.username() OR photo_security.flag('main_admin'))) AND (photo_security.assign_folder(folder_id) OR photo_security.keeps_folder(event_id,folder_id)));
CREATE POLICY app_delete ON public.events FOR DELETE TO personal_photos_app USING((photo_security.flag('can_write') AND (owner_username=photo_security.username() OR photo_security.flag('main_admin'))));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.events TO personal_photos_maintenance;
CREATE POLICY maintenance ON public.events TO personal_photos_maintenance USING(true) WITH CHECK(true);
